package engine

import (
	"fmt"
	"path/filepath"

	"github.com/vigolium/vigolium/pkg/olium/tool"
)

// toolArchivePointer keeps model context bounded without sending the operator
// back to re-execute side-effecting commands. The receipt is generated by the
// archive wrapper, not by the provider. Binary files remain the authoritative
// bytes; read_file is only a model-side preview/hydration aid.
func (e *Engine) toolArchivePointer(res tool.Result) string {
	if e.cfg.SpillDir == "" {
		return ""
	}
	receipt, ok := res.Details[tool.ArchiveDetailsKey].(map[string]any)
	if !ok {
		return ""
	}
	path, _ := receipt["result"].(string)
	if streams, ok := receipt["streams"].(map[string]any); ok {
		if combined, ok := streams["combined"].(map[string]any); ok {
			if raw, ok := combined["path"].(string); ok {
				path = raw
			}
		}
	}
	if path == "" {
		return "\n\n[Tool archiving failed; omitted output may not be recoverable.]"
	}
	status := "complete"
	if complete, _ := receipt["complete"].(bool); !complete {
		status = "incomplete; bytes may be missing"
	}
	return fmt.Sprintf("\n\n[Tool archive %s. Inspect saved bytes with `"+spillPointerMarker+"%q` (bounded offset/limit); do not rerun the command to recover output.]", status, filepath.Join(e.cfg.SpillDir, filepath.FromSlash(path)))
}
